function normal(r,e){const d=[e.b[0]-e.a[0],e.b[1]-e.a[1]],l=Math.hypot(...d),sign=S.areaOf(S.points(r))>=0?1:-1;return[d[1]/l*sign,-d[0]/l*sign];}
function down(e){if(e.button!==0||B3D()||e.ctrlKey||e.metaKey)return;const r=room(selected),p=e.shiftKey&&cursor?cursor:pointOf(e),v=e.target.closest?.('[data-shape-vertex]'),insert=e.target.closest?.('[data-shape-insert]'),radius=e.target.closest?.('[data-shape-radius]'),adjoin=e.target.closest?.('[data-shape-adjoin]');if(tool==='pen'){e.preventDefault();e.stopImmediatePropagation();if(draft.length>=3&&Math.hypot(p.x-draft[0].x,p.y-draft[0].y)<worldPixels(12)){finishPen();return;}if(!draft.length)scope=currentBuilding().id+':'+floorId;draft.push(p);draw();return;}if(adjoin&&eligible(r)){e.preventDefault();e.stopImmediatePropagation();const edge=S.edges(r).find(x=>x.id===adjoin.dataset.shapeAdjoin);if(!edge)return;const n=normal(r,edge);gesture={adjoin:true,edge,n,ps:[edge.a,edge.b,edge.b,edge.a],pointerId:e.pointerId,start:point(e),scope:currentBuilding().id+':'+floorId};$('plan').setPointerCapture(e.pointerId);return;}
if((v||insert||radius)&&current()){e.preventDefault();e.stopImmediatePropagation();const before=JSON.stringify(model);prepare(r);let index=radius?Number(radius.dataset.shapeRadius):v?Number(v.dataset.shapeVertex):Number(insert.dataset.shapeInsert)+1;if(insert){const vs=clone(S.vertices(r)),ps=S.raw(r),prev=index-1,q=ps[index%ps.length],a=ps[prev];ps.splice(index,0,[(a[0]+q[0])/2,(a[1]+q[1])/2]);vs.splice(index,0,{id:'p'+Date.now().toString(36),r:0});if(!changed(r,ps,vs))return;}vertex=index;gesture={before,room:r.id,index,radius:!!radius,original:clone(r),pointerId:e.pointerId,scope:currentBuilding().id+':'+floorId};$('plan').setPointerCapture(e.pointerId);draw();return;}}
function move(e){if(B3D())return;const p=pointOf(e);if(tool==='pen'&&draft.length){cursor=p;if(e.shiftKey){const a=draft.at(-1),dx=p.x-a.x,dy=p.y-a.y,angle=Math.round(Math.atan2(dy,dx)/(Math.PI/4))*Math.PI/4,l=Math.hypot(dx,dy);cursor={x:a.x+Math.cos(angle)*l,y:a.y+Math.sin(angle)*l};}draw();return;}if(gesture){e.preventDefault();e.stopImmediatePropagation();if(gesture.adjoin){const depth=Math.max(.5,snap((p.x-gesture.start.x)*gesture.n[0]+(p.y-gesture.start.y)*gesture.n[1])),a=gesture.edge.a,b=gesture.edge.b,n=gesture.n;gesture.ps=[b,a,[a[0]+n[0]*depth,a[1]+n[1]*depth],[b[0]+n[0]*depth,b[1]+n[1]*depth]];}else{const r=room(gesture.room),ps=S.raw(gesture.original);if(gesture.radius){const center=ps[gesture.index];r.shape.vertices[gesture.index].r=Math.min(50,Math.round(Math.hypot(p.x-center[0],p.y-center[1])*10)/10);syncStairEdit(r);draw();return;}ps[gesture.index]=[p.x,p.y];changed(r,ps,clone(S.vertices(gesture.original)));}draw();return;}const r=room(selected);if(tool==='select'&&eligible(r)){if(e.target.closest?.('[data-shape-adjoin]'))return;const near=nearestEdge(point(e),r),next=near&&!near.curved&&near.hit.distance<worldPixels(12)?near:null;if(next?.id!==hoverEdge?.id){hoverEdge=next;draw();}}}
